    [4601] = {
        achievementId = 4601,
        name = "Been Waiting a Long Time for This (10 player)",
        category = "Raids",
        sourceType = "Achievement",
        source = "Been Waiting a Long Time for This (10 player)",
        acquisition = "Difficulty: Hard - Hold the Lich King in phase one and maintain a plague chain until the actual Necrotic Plague reaches thirty stacks.\n\n1. Outside Icecrown Citadel, set Legacy Raid Size to 10 players and Raid Difficulty to NORMAL (Heroic also satisfies this achievement). Enter the RAID portal at 53.5, 85.5 in Icecrown; the higher Frozen Halls dungeon entrance is different.\n\n2. Clear the Lower Spire, then the Plagueworks (Festergut, Rotface and Putricide), Crimson Hall (Blood Princes and Lana'thel), and Frostwing path to Sindragosa. Activate both valves after Festergut and Rotface so Putricide's room opens. The three wing-end bosses unlock the central Upper Spire transporter to the Frozen Throne.\n\n3. Speak to Tirion, dismiss attacking pets and remove automatic retaliation damage. Do not damage the Lich King or his adds. Stand on the LOWER few stairs with your back toward the throne; Normal avoids Heroic's Shadow Traps entirely.\n\n4. Let him summon ghouls while Necrotic Plague jumps between you and nearby adds. Its disappearance from YOUR debuff bar is normal: it is travelling through the pack. Keep the pack together and wait until Necrotic Plague reaches at least THIRTY stacks on a current carrier. Plague Siphon on the boss is a different effect.\n\n5. Only after seeing 30 or more Necrotic Plague stacks, attack and push the boss into his ending. Speak to Tirion Fordring at the Frozen Throne, then attack the Lich King. At the scripted raid-kill scene, DO NOT release or leave. Wait for Tirion and Terenas's dialogue, accept the resurrection when offered, and finish the suspended Lich King after Tirion breaks Frostmourne.",
        stepCount = 5,
        waypoints = {
            { mapID = 118, x = 0.535, y = 0.855, step = 1, label = "Icecrown Citadel - raid entrance" },
            {
                mapID = 192,
                x = 0.498,
                y = 0.528,
                step = 3,
                label = "Lower stairs - no damage while plague builds",
                mapName = "Icecrown Citadel - The Frozen Throne",
            },
            {
                mapID = 192,
                x = 0.498,
                y = 0.528,
                step = 4,
                label = "Wait for 30+ Necrotic Plague stacks",
                mapName = "Icecrown Citadel - The Frozen Throne",
            },
            {
                mapID = 192,
                x = 0.498,
                y = 0.528,
                step = 5,
                label = "Finish after Tirion and Terenas's ending",
                mapName = "Icecrown Citadel - The Frozen Throne",
            },
        },
        tips = "Modern Retail solo reports do not require a pet, summoned guardian, exactly 30 stacks, or a disease dispeller. Heal yourself if needed. Do not stand so high on the throne stairs that a Heroic trap can throw you off the back.",
        sources = {
            "https://www.wowhead.com/achievement=4601#comments:id=6022006",
            "https://www.wowhead.com/achievement=4601#comments:id=6025458",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=4601",
        sourceURL = "https://www.wowhead.com/achievement=4601#comments",
        difficultyReason = "Hold the Lich King in phase one and maintain a plague chain until the actual Necrotic Plague reaches thirty stacks.",
        difficulty = "hard",
    },
    [4602] = {
