    [4611] = {
        achievementId = 4611,
        name = "Full House (25 player)",
        category = "Raids",
        sourceType = "Achievement",
        source = "Full House (25 player)",
        acquisition = "Difficulty: Medium - Preserve five distinct transformed cultist types, then kill only Lady Deathwhisper while all five survive.\n\n1. Outside Icecrown Citadel, set Legacy Raid Size to 25 players and Raid Difficulty to NORMAL (Heroic also satisfies this achievement). Enter the RAID portal at 53.5, 85.5 in Icecrown; the higher Frozen Halls dungeon entrance is different.\n\n2. Defeat Marrowgar and clear ALL the ordinary trash in front of Lady Deathwhisper. Those trash packs do not count. Disable retaliation damage, cleave and pet attacks, then walk up to her to enter combat WITHOUT damaging her mana shield.\n\n3. Wait while she summons and transforms cultists. Keep the shield intact so more waves can arrive. The reliable five types are Cult Fanatic, Deformed Fanatic, Reanimated Fanatic, Cult Adherent and Reanimated Adherent. Keep at least ONE OF EACH alive simultaneously; merely having five enemies is insufficient.\n\n4. Use separate /targetexact macros or inspect nameplates to identify all five types. For marking in Midnight, use /tm 1 through /tm 5 on five separate buttons; old scripted SetRaidTarget combat macros may fail. A transformation can take several minutes: continue waiting if only three or four types are present.\n\n5. Once all five types are active, kill ONLY Lady Deathwhisper with direct single-target damage. Leave every required cultist alive until she dies. Her shield must be depleted as part of this final kill, not while you are waiting for spawns.",
        stepCount = 5,
        waypoints = {
            { mapID = 118, x = 0.535, y = 0.855, step = 1, label = "Icecrown Citadel - raid entrance" },
