                y = 0.867,
                step = 2,
                label = "Lady Deathwhisper",
                mapName = "Icecrown Citadel - Lower Citadel",
            },
        },
        tips = "In a group, alternate boarding teams if more trips are needed. A fast solo cannon kill needs zero visits; the 25-player limit is stricter than the 10-player limit.",
