    [4615] = {
        achievementId = 4615,
        name = "Flu Shot Shortage (25 player)",
        category = "Raids",
        sourceType = "Achievement",
        source = "Flu Shot Shortage (25 player)",
        acquisition = "Difficulty: Easy - Kill promptly or use the short prescribed gunship route before the prohibited Icecrown mechanic can occur.\n\n1. Outside Icecrown Citadel, set Legacy Raid Size to 25 players and Raid Difficulty to NORMAL (Heroic also satisfies this achievement). Enter the RAID portal at 53.5, 85.5 in Icecrown; the higher Frozen Halls dungeon entrance is different.\n\n2. Clear the Lower Spire: Marrowgar, Deathwhisper, Gunship Battle and Saurfang. Wait for Saurfang's dialogue, then take the transporter to the Upper Spire. Choose the branch named in the next step.\n\n3. Enter Festergut's Plagueworks room and kill him promptly. No player may ever reach THREE Inoculated stacks. A fast kill before spores appear is valid; there is no requirement to wait through Pungent Blight.\n\n4. If spores do appear, stay away from exploding spores once you have two stacks. In a group, spread the spore holders so they do not give an unwanted third stack to another player. Finish the boss before the next cycle causes a failure.",
        stepCount = 4,
        waypoints = {
